#ifndef OUI_REGISTRY_H
#define OUI_REGISTRY_H

#include <stddef.h>
#include <stdint.h>

// Optional IEEE MA-L (OUI) vendor registry, read through storage_manager.h's
// board-agnostic filesystem (SD on boards that have a card slot, LittleFS on
// the StickS3 — see storageFilesystem()). The file is generated by
// tools/build_oui_registry.py and searched in place; it is never loaded into
// RAM. Returns false when storage/the file is absent, malformed, or has no
// match for this OUI (station_scan.cpp falls back to its small built-in
// vendor table in that case, same as when this registry isn't present at all).
bool ouiRegistryLookup(const uint8_t mac[6], char *name, size_t nameSize);

#endif
